    <div><label class="mb-2 block text-sm font-medium dark:text-white">Jenis jawaban</label>
     <div class="hmif-question-type-wrapper" x-on:click.outside="open=false" x-on:keydown.escape.stop="open=false;$refs.trigger.focus()">
      <button x-ref="trigger" type="button" class="hmif-type-trigger flex w-full items-center justify-between gap-3 rounded-lg px-3 py-2 text-left text-sm" x-bind:aria-expanded="open" aria-haspopup="listbox" x-on:click="open=!open;if(open){activeIndex=Math.max(0,questionTypes.findIndex(type=>type.value===question.type));$nextTick(()=>$refs.listbox.focus())}" x-on:keydown.arrow-down.prevent="open=true;activeIndex=Math.max(0,questionTypes.findIndex(type=>type.value===question.type));$nextTick(()=>$refs.listbox.focus())" x-on:keydown.arrow-up.prevent="open=true;activeIndex=Math.max(0,questionTypes.findIndex(type=>type.value===question.type));$nextTick(()=>$refs.listbox.focus())">
       <span class="flex min-w-0 items-center gap-3"><x-filament::icon x-show="question.type==='short_text'" x-cloak icon="heroicon-o-bars-2" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='paragraph'" x-cloak icon="heroicon-o-bars-3-bottom-left" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='radio'" x-cloak icon="heroicon-o-stop-circle" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='checkbox'" x-cloak icon="heroicon-o-check-circle" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='select'" x-cloak icon="heroicon-o-chevron-down" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='email'" x-cloak icon="heroicon-o-envelope" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='number'" x-cloak icon="heroicon-o-hashtag" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='date'" x-cloak icon="heroicon-o-calendar-days" class="hmif-type-icon"/><x-filament::icon x-show="question.type==='file_upload'" x-cloak icon="heroicon-o-paper-clip" class="hmif-type-icon"/><span class="truncate" x-text="questionTypeLabel(question.type)"></span></span>
       <x-filament::icon icon="heroicon-m-chevron-down" class="h-5 w-5 shrink-0 transition-transform" x-bind:class="{'rotate-180':open}"/>
