       <template x-for="(type,typeIndex) in questionTypes" :key="type.value"><button type="button" role="option" class="hmif-type-option flex w-full items-center justify-between rounded-md px-3 py-2 text-left text-sm" x-bind:class="{'hmif-type-option-active':activeIndex===typeIndex,'hmif-type-option-selected':question.type===type.value,'hmif-type-option-separator':type.separator}" x-bind:aria-selected="question.type===type.value" x-on:mouseenter="activeIndex=typeIndex" x-on:click="selectQuestionType(question,type.value);open=false;$refs.trigger.focus()"><span class="flex min-w-0 flex-1 items-center gap-3"><x-filament::icon x-show="type.value==='short_text'" x-cloak icon="heroicon-o-bars-2" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='paragraph'" x-cloak icon="heroicon-o-bars-3-bottom-left" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='radio'" x-cloak icon="heroicon-o-stop-circle" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='checkbox'" x-cloak icon="heroicon-o-check-circle" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='select'" x-cloak icon="heroicon-o-chevron-down" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='email'" x-cloak icon="heroicon-o-envelope" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='number'" x-cloak icon="heroicon-o-hashtag" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='date'" x-cloak icon="heroicon-o-calendar-days" class="hmif-type-icon"/><x-filament::icon x-show="type.value==='file_upload'" x-cloak icon="heroicon-o-paper-clip" class="hmif-type-icon"/><span class="truncate" x-text="type.label"></span></span><x-filament::icon x-show="question.type===type.value" x-cloak icon="heroicon-m-check" class="h-5 w-5 shrink-0 text-primary-600 dark:text-primary-400"/></button></template>
