   <div x-show="question.type==='short_text'" class="mt-5"><input type="text" draggable="false" class="hmif-short-answer-preview text-sm" placeholder="Short answer text" x-model="previewAnswers[question.client_id]"></div>
   <div x-show="question.type==='paragraph'" class="mt-5"><textarea draggable="false" rows="4" class="hmif-short-answer-preview hmif-paragraph-preview text-sm" placeholder="Long answer text" x-model="previewAnswers[question.client_id]"></textarea></div>
   <div x-show="!['short_text','paragraph','file_upload'].includes(question.type)&&!needsOptions(question.type)" class="hmif-answer-preview mt-5 rounded-lg px-4 py-3 text-sm"><span x-text="question.type==='date'?'Date':(question.type==='email'?'Email address':(question.type==='number'?'Number':'Short answer text'))"></span><div class="mt-2 border-b border-dashed border-gray-300 dark:border-white/20"></div></div>
