   <div x-show="needsOptions(question.type)" x-cloak class="mt-5 space-y-3"><label class="block text-sm font-medium dark:text-white">Opsi</label><template x-for="(option,optionIndex) in question.options" :key="option.client_id"><div class="flex items-center gap-3"><span class="w-6 text-center text-gray-500" x-text="question.type==='select'?(optionIndex+1)+'.':(question.type==='checkbox'?'□':'○')"></span><x-filament::input.wrapper class="min-w-0 flex-1"><x-filament::input x-model="option.label" x-on:input="dirty()" required/></x-filament::input.wrapper><x-filament::icon-button type="button" color="danger" icon="heroicon-m-trash" label="Hapus opsi" x-on:click="removeOption(question,optionIndex)"/></div></template><x-filament::button type="button" size="sm" color="gray" icon="heroicon-m-plus" x-on:click="addOption(question)">Tambah opsi</x-filament::button></div>
   <label class="mt-5 flex items-center gap-3 text-sm dark:text-white"><input type="checkbox" x-model="question.required" x-on:change="dirty()" class="rounded">Required</label>
  </article></template></div><div class="mt-4"><x-filament::button type="button" color="gray" icon="heroicon-m-plus" x-on:click.stop="addQuestion(section.client_id)">Tambah Pertanyaan</x-filament::button></div>
   <div class="hmif-section-navigation mt-4"><label class="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-200" x-text="'After section '+(sectionIndex+1)"></label><select x-bind:value="sectionNavigationValue(section)" x-on:change="setSectionNavigation(section,$event.target.value)"><option value="continue_next">Lanjut ke bagian berikutnya</option><template x-for="(target,targetIndex) in builder.sections.filter(item=>item.client_id!==section.client_id)" :key="target.client_id"><option x-bind:value="'section:'+target.client_id" x-text="'Pergi ke Section '+(builder.sections.findIndex(item=>item.client_id===target.client_id)+1)+(target.title?' — '+target.title:'')"></option></template><option value="submit">Kirim formulir</option></select></div>
  </section></template><div><x-filament::button type="button" color="gray" outlined icon="heroicon-m-rectangle-stack" x-on:click="addSection()">Add Section</x-filament::button></div></div>
  <div x-show="sectionDeleteIndex!==null" x-cloak class="fixed inset-0 z-[3000] grid place-items-center p-4" role="dialog" aria-modal="true" aria-labelledby="delete-section-title"><button type="button" class="absolute inset-0 bg-gray-950/60" aria-label="Batal" x-on:click="sectionDeleteIndex=null"></button><div class="relative w-full max-w-md rounded-xl bg-white p-6 shadow-2xl dark:bg-gray-900"><h2 id="delete-section-title" class="text-lg font-semibold text-gray-950 dark:text-white">Hapus Section?</h2><p class="mt-2 text-sm text-gray-600 dark:text-gray-300">Semua pertanyaan dan opsi di dalam section ini juga akan dihapus.</p><div class="mt-6 flex justify-end gap-2"><x-filament::button type="button" color="gray" x-on:click="sectionDeleteIndex=null">Batal</x-filament::button><x-filament::button type="button" color="danger" x-on:click="confirmDeleteSection()">Hapus Section</x-filament::button></div></div></div>
  <aside class="hmif-theme-panel" x-show="themePanelOpen" x-cloak x-transition:enter="transition ease-out duration-200" x-transition:enter-start="translate-x-full" x-transition:enter-end="translate-x-0" x-transition:leave="transition ease-in duration-200" x-transition:leave-start="translate-x-0" x-transition:leave-end="translate-x-full" aria-label="Theme customizer">
   <div class="hmif-theme-panel-header"><div class="flex items-center gap-2 font-semibold text-gray-950 dark:text-white"><x-filament::icon icon="heroicon-o-swatch" class="h-5 w-5"/>Theme</div><x-filament::icon-button type="button" icon="heroicon-m-x-mark" label="Tutup Theme" x-on:click="themePanelOpen=false"/></div>
   <div class="hmif-theme-panel-body">
    <section class="hmif-theme-section space-y-4"><h3 class="font-semibold text-gray-950 dark:text-white">Text style</h3>
     <template x-for="control in themeTextControls" :key="control.key"><div><label class="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-200" x-text="control.label"></label><div class="grid grid-cols-[1fr_90px] gap-2"><select class="hmif-theme-select" x-model="builder.theme[control.key+'_font']" x-on:change="dirty()"><template x-for="font in themeFonts" :key="font"><option x-bind:value="font" x-text="font"></option></template></select><select class="hmif-theme-select" x-model.number="builder.theme[control.key+'_size']" x-on:change="dirty()"><template x-for="size in control.sizes" :key="size"><option x-bind:value="size" x-text="size+' px'"></option></template></select></div></div></template>
    </section>
    <section class="hmif-theme-section space-y-3"><h3 class="font-semibold text-gray-950 dark:text-white">Header</h3><div x-show="themeHeaderPreview" class="overflow-hidden rounded-lg border border-gray-200 dark:border-white/10"><img x-bind:src="themeHeaderPreview" class="h-32 w-full object-cover" alt="Preview header"></div><input x-ref="themeHeaderInput" class="hidden" type="file" name="theme_header_image" accept="image/jpeg,image/png,image/webp" x-on:change="chooseThemeHeader($event)"><div class="flex gap-2"><x-filament::button type="button" size="sm" color="gray" x-on:click="$refs.themeHeaderInput.click()" x-text="themeHeaderPreview?'Change':'Choose Image'"></x-filament::button><x-filament::button x-show="themeHeaderPreview" type="button" size="sm" color="danger" outlined x-on:click="removeThemeHeader()">Remove</x-filament::button></div><p class="text-xs text-gray-500 dark:text-gray-400">JPG, PNG, atau WebP. Maksimal 5 MB.</p></section>
    <section class="hmif-theme-section space-y-3"><h3 class="font-semibold text-gray-950 dark:text-white">Color</h3><div class="hmif-theme-palette"><template x-for="color in themeColors" :key="color"><button type="button" class="hmif-theme-swatch" x-bind:class="{'is-selected':builder.theme.primary_color===color}" x-bind:style="{'background-color':color,'--swatch':color,color:contrastColor(color)}" x-on:click="builder.theme.primary_color=color;dirty()" x-bind:aria-label="'Pilih warna '+color" x-bind:aria-pressed="builder.theme.primary_color===color"><x-filament::icon x-show="builder.theme.primary_color===color" icon="heroicon-m-check" class="h-4 w-4"/></button></template><button x-show="!themeColors.includes(builder.theme.primary_color)" type="button" class="hmif-theme-swatch is-selected" x-bind:style="{'background-color':builder.theme.primary_color,'--swatch':builder.theme.primary_color,color:contrastColor(builder.theme.primary_color)}" x-on:click="$refs.customPrimaryColor.click()" aria-label="Warna custom aktif" aria-pressed="true"><x-filament::icon icon="heroicon-m-check" class="h-4 w-4"/></button><button type="button" class="hmif-theme-swatch bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-white" x-on:click="$refs.customPrimaryColor.click()" aria-label="Pilih custom color"><x-filament::icon icon="heroicon-m-plus" class="h-4 w-4"/></button><input x-ref="customPrimaryColor" type="color" class="hmif-theme-custom-input" x-model="builder.theme.primary_color" x-on:input="dirty()" tabindex="-1" aria-hidden="true"></div></section>
    <section class="hmif-theme-section space-y-3"><h3 class="font-semibold text-gray-950 dark:text-white">Background</h3><div class="hmif-theme-palette"><template x-for="color in backgroundColors" :key="color"><button type="button" class="hmif-theme-swatch" x-bind:class="{'is-selected':builder.theme.background_color===color}" x-bind:style="{'background-color':color,'--swatch':color,color:contrastColor(color)}" x-on:click="builder.theme.background_color=color;builder.theme.surface_color=surfaceFor(color);dirty()" x-bind:aria-label="'Pilih background '+color" x-bind:aria-pressed="builder.theme.background_color===color"><x-filament::icon x-show="builder.theme.background_color===color" icon="heroicon-m-check" class="h-4 w-4"/></button></template><button x-show="!backgroundColors.includes(builder.theme.background_color)" type="button" class="hmif-theme-swatch is-selected" x-bind:style="{'background-color':builder.theme.background_color,'--swatch':builder.theme.background_color,color:contrastColor(builder.theme.background_color)}" x-on:click="$refs.customBackgroundColor.click()" aria-label="Background custom aktif" aria-pressed="true"><x-filament::icon icon="heroicon-m-check" class="h-4 w-4"/></button><button type="button" class="hmif-theme-swatch bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-white" x-on:click="$refs.customBackgroundColor.click()" aria-label="Pilih custom background"><x-filament::icon icon="heroicon-m-plus" class="h-4 w-4"/></button><input x-ref="customBackgroundColor" type="color" class="hmif-theme-custom-input" x-model="builder.theme.background_color" x-on:input="builder.theme.surface_color=surfaceFor(builder.theme.background_color);dirty()" tabindex="-1" aria-hidden="true"></div></section>
    <x-filament::button type="button" color="gray" outlined icon="heroicon-m-arrow-path" x-on:click="resetTheme()">Reset theme</x-filament::button>
   </div>
  </aside>
 </form>
