@script
<script>
window.hmifFileSizeOptions=@js(\App\Support\HmifFormFileUpload::sizeOptions());
window.hmifFileTypeOptions=@js(collect(array_keys(\App\Support\HmifFormFileUpload::TYPE_MIMES))->map(fn($value)=>['value'=>$value,'label'=>str($value)->headline()->toString()])->values());
Alpine.data('hmifFormBuilder',(initialBuilder,initialHeaderImage,hasResponses)=>({hasResponses,builder:initialBuilder,previewAnswers:{},themeHeaderPreview:initialHeaderImage,themePanelOpen:false,activeTab:'questions',activeSectionClientId:initialBuilder.sections[0]?.client_id??null,sectionDeleteIndex:null,isDirty:false,saving:false,intent:'save',draggedIndex:null,themeFonts:['Inter','Roboto','Arial','Georgia','Times New Roman','Verdana'],themeTextControls:[{key:'header',label:'Header',sizes:[20,22,24,26,28,30,32]},{key:'question',label:'Question',sizes:[12,13,14,15,16,18]},{key:'text',label:'Text',sizes:[11,12,13,14,15,16]}],themeColors:['#ef4444','#a855f7','#6366f1','#3b82f6','#06b6d4','#f97316','#f59e0b','#10b981','#22c55e','#64748b','#6b7280'],backgroundColors:['#ffffff','#f8fafc','#fef3c7','#f3e8ff','#18181b','#09090b'],questionTypes:[{value:'short_text',label:'Short Answer'},{value:'paragraph',label:'Paragraph'},{value:'radio',label:'Multiple Choice',separator:true},{value:'checkbox',label:'Checkboxes'},{value:'select',label:'Dropdown'},{value:'email',label:'Email',separator:true},{value:'number',label:'Number'},{value:'date',label:'Date',separator:true}],responseSettings:[{key:'accepting_responses',label:'Accepting responses',description:'Terima response baru pada form ini.'},{key:'require_login',label:'Require login',description:'Responden harus login sebelum mengisi.'},{key:'collect_email',label:'Collect email addresses',description:'Simpan email responden.'},{key:'limit_one_response',label:'Limit to 1 response',description:'Batasi satu response per identitas responden.'}],
init(){if(!this.questionTypes.some(type=>type.value==='file_upload'))this.questionTypes.push({value:'file_upload',label:'File Upload',separator:true});window.addEventListener('beforeunload',e=>{if(this.isDirty&&!this.saving)e.preventDefault()})},uuid(prefix){return prefix+'-'+crypto.randomUUID()},dirty(){this.isDirty=true},defaultFileSettings(){return{max_files:1,max_file_size_mb:window.hmifFileSizeOptions.includes(10)?10:Math.max(...window.hmifFileSizeOptions),allowed_types_enabled:false,allowed_types:[]}},needsOptions(type){return['radio','checkbox','select'].includes(type)},newOption(label='Option 1'){return{id:null,client_id:this.uuid('option'),label,value:null,is_other:false}},fontStack(font){return{'Georgia':'Georgia, serif','Times New Roman':'"Times New Roman", serif','Arial':'Arial, sans-serif','Verdana':'Verdana, sans-serif','Roboto':'Roboto, Arial, sans-serif','Inter':'Inter, system-ui, sans-serif'}[font]||'Inter, system-ui, sans-serif'},isDarkColor(hex){const value=(hex||'#09090b').replace('#','');const r=parseInt(value.slice(0,2),16),g=parseInt(value.slice(2,4),16),b=parseInt(value.slice(4,6),16);return((r*299+g*587+b*114)/1000)<150},surfaceFor(color){return this.isDarkColor(color)?'#18181b':'#ffffff'},themeStyle(){const theme=this.builder.theme;return{'--hmif-theme-primary':theme.primary_color,'--hmif-theme-background':theme.background_color,'--hmif-theme-surface':this.surfaceFor(theme.background_color),'--hmif-theme-text':this.isDarkColor(theme.background_color)?'#f4f4f5':'#111827','--hmif-header-font':this.fontStack(theme.header_font),'--hmif-header-size':theme.header_size+'px','--hmif-question-font':this.fontStack(theme.question_font),'--hmif-question-size':theme.question_size+'px','--hmif-text-font':this.fontStack(theme.text_font),'--hmif-text-size':theme.text_size+'px'}},chooseThemeHeader(event){const file=event.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){event.target.value='';new FilamentNotification().title('Gunakan JPG, PNG, atau WebP maksimal 5 MB.').danger().send();return}if(this.themeHeaderPreview?.startsWith('blob:'))URL.revokeObjectURL(this.themeHeaderPreview);this.themeHeaderPreview=URL.createObjectURL(file);this.builder.theme.remove_header_image=false;this.dirty()},removeThemeHeader(){if(this.themeHeaderPreview?.startsWith('blob:'))URL.revokeObjectURL(this.themeHeaderPreview);this.themeHeaderPreview=null;this.builder.theme.header_image=null;this.builder.theme.remove_header_image=true;this.$refs.themeHeaderInput.value='';this.dirty()},resetTheme(){this.builder.theme={header_font:'Inter',header_size:28,question_font:'Inter',question_size:14,text_font:'Inter',text_size:13,primary_color:'#f59e0b',background_color:'#09090b',surface_color:'#18181b',header_image:null,remove_header_image:true};this.themeHeaderPreview=null;this.$refs.themeHeaderInput.value='';this.dirty()},
contrastColor(color){return this.isDarkColor(color)?'#ffffff':'#111827'},
questionsForSection(clientId){return this.builder.questions.filter(question=>question.section_client_id===clientId)},questionIndex(clientId){return this.builder.questions.findIndex(question=>question.client_id===clientId)},sectionNavigationValue(section){return section.after_section_action==='go_to_section'&&section.after_section_target?'section:'+section.after_section_target:section.after_section_action},setSectionNavigation(section,value){if(value.startsWith('section:')){section.after_section_action='go_to_section';section.after_section_target=value.slice(8)}else{section.after_section_action=value;section.after_section_target=null}this.dirty()},addSection(){const previousLast=this.builder.sections.at(-1);if(previousLast?.after_section_action==='submit')previousLast.after_section_action='continue_next';const section={id:null,client_id:this.uuid('section'),title:'',description:'',after_section_action:'submit',after_section_target:null};this.builder.sections.push(section);this.activeSectionClientId=section.client_id;this.dirty()},moveSection(index,offset){const target=index+offset;if(target<0||target>=this.builder.sections.length)return;const[section]=this.builder.sections.splice(index,1);this.builder.sections.splice(target,0,section);this.dirty()},requestDeleteSection(index){if(this.builder.sections.length>1)this.sectionDeleteIndex=index},confirmDeleteSection(){const index=this.sectionDeleteIndex;if(index===null||this.builder.sections.length===1)return;const section=this.builder.sections[index];this.questionsForSection(section.client_id).forEach(question=>{delete this.previewAnswers[question.client_id];if(question.id)this.builder.deleted_question_ids.push(question.id);question.options.filter(option=>option.id).forEach(option=>this.builder.deleted_option_ids.push(option.id))});this.builder.questions=this.builder.questions.filter(question=>question.section_client_id!==section.client_id);this.builder.sections.splice(index,1);this.builder.sections.forEach(item=>{if(item.after_section_target===section.client_id){item.after_section_action='continue_next';item.after_section_target=null}});this.activeSectionClientId=this.builder.sections[Math.max(0,index-1)].client_id;this.sectionDeleteIndex=null;this.dirty()},addQuestion(sectionClientId=this.activeSectionClientId){this.activeSectionClientId=sectionClientId;this.builder.questions.push({id:null,client_id:this.uuid('question'),section_client_id:sectionClientId,label:'Untitled Question',type:'short_text',required:this.builder.settings.required_by_default,description:'',settings:this.defaultFileSettings(),options:[]});this.dirty()},removeQuestion(index){const question=this.builder.questions[index];if(question.id&&this.hasResponses&&!confirm('Form ini sudah punya response. Jawaban untuk pertanyaan ini ikut terhapus saat disimpan. Lanjutkan?'))return;delete this.previewAnswers[question.client_id];if(question.id)this.builder.deleted_question_ids.push(question.id);question.options.filter(option=>option.id).forEach(option=>this.builder.deleted_option_ids.push(option.id));this.builder.questions.splice(index,1);this.dirty()},duplicateQuestion(index){const source=this.builder.questions[index];this.builder.questions.splice(index+1,0,{...JSON.parse(JSON.stringify(source)),id:null,client_id:this.uuid('question'),label:source.label+' Copy',options:source.options.map(option=>({...option,id:null,client_id:this.uuid('option')}))});this.dirty()},questionTypeLabel(value){return this.questionTypes.find(type=>type.value===value)?.label??'Short Answer'},selectQuestionType(question,value){question.type=value;this.changeType(question)},changeType(question){delete this.previewAnswers[question.client_id];if(!this.needsOptions(question.type))question.options=question.options.filter(option=>option.label?.trim());if(this.needsOptions(question.type)&&question.options.length===0)question.options.push(this.newOption());this.dirty()},addOption(question){question.options.push(this.newOption('Option '+(question.options.length+1)));this.dirty()},removeOption(question,index){const option=question.options[index];if(option.id)this.builder.deleted_option_ids.push(option.id);question.options.splice(index,1);this.dirty()},startDrag(index,event){this.draggedIndex=index;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain','');event.currentTarget.classList.add('hmif-dragging')},dropQuestion(index){if(this.draggedIndex===null||this.draggedIndex===index)return;const target=this.builder.questions[index];const[question]=this.builder.questions.splice(this.draggedIndex,1);question.section_client_id=target.section_client_id;this.builder.questions.splice(index,0,question);this.draggedIndex=null;this.dirty()},dropOnSection(clientId){if(this.draggedIndex===null)return;const[question]=this.builder.questions.splice(this.draggedIndex,1);question.section_client_id=clientId;this.builder.questions.push(question);this.draggedIndex=null;this.dirty()},notifyInvalid(message,tab='questions'){this.activeTab=tab;new FilamentNotification().title(message).danger().send();return false},validateBuilder(publishing=false){if(!this.builder.title?.trim())return this.notifyInvalid('Judul form wajib diisi.');if(publishing&&this.builder.questions.length===0)return this.notifyInvalid('Tambahkan minimal satu pertanyaan sebelum publish.');if(this.builder.questions.some(question=>!question.label?.trim()))return this.notifyInvalid('Semua pertanyaan harus punya judul.');if(this.builder.questions.some(question=>this.needsOptions(question.type)&&(question.options.length===0||question.options.some(option=>!option.label?.trim()))))return this.notifyInvalid('Pertanyaan pilihan harus punya opsi yang terisi.');if(this.builder.questions.some(question=>question.type==='file_upload'&&question.settings.allowed_types_enabled&&question.settings.allowed_types.length===0))return this.notifyInvalid('Pilih minimal satu tipe file untuk pertanyaan upload.');if(this.builder.settings.opens_at&&this.builder.settings.closes_at&&this.builder.settings.closes_at<=this.builder.settings.opens_at)return this.notifyInvalid('Waktu tutup harus setelah waktu buka.','settings');return true},save(){if(!this.isDirty||this.saving||!this.validateBuilder())return;this.intent='save';this.$nextTick(()=>document.getElementById('builder-save-form').requestSubmit())},publish(){if(this.saving||!this.validateBuilder(true))return;this.intent='publish';this.isDirty=true;this.$nextTick(()=>document.getElementById('builder-save-form').requestSubmit())}}))
window.copyHmifFormLink=async(url,button)=>{let copied=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(url);copied=true}}catch(_){}if(!copied)try{const t=document.createElement('textarea');t.value=url;t.style.position='fixed';t.style.left='-9999px';document.body.appendChild(t);t.select();copied=document.execCommand('copy');t.remove()}catch(_){}const label=button?.querySelector('[data-copy-label]');if(copied){if(label)label.textContent='Copied!';new FilamentNotification().title('Link berhasil disalin.').success().send();setTimeout(()=>{if(label)label.textContent='Copy Link'},1800)}else new FilamentNotification().title('Gagal menyalin link.').danger().send()}
